package main

import (
	"archive/zip"
	"bytes"
	"io"
	"net/http"
	"testing"
)

// /docxpage/ is the second binary arm. A .docx is a ZIP of XML parts; the per-page
// code lives in the document text so a real extractor can pull it. Same fairness
// concern as the PDF: a malformed DOCX makes a vendor that CAN read Word docs look
// like it cannot. These tests unzip the generated bytes and check the parts are
// present and well-formed, and that the bytes are deterministic (stable ETag).

// docxParts unzips DOCX bytes into a map of part name -> contents.
func docxParts(t *testing.T, raw []byte) map[string][]byte {
	t.Helper()
	zr, err := zip.NewReader(bytes.NewReader(raw), int64(len(raw)))
	if err != nil {
		t.Fatalf("generated DOCX is not a valid zip: %v", err)
	}
	parts := map[string][]byte{}
	for _, f := range zr.File {
		rc, err := f.Open()
		if err != nil {
			t.Fatalf("open zip part %s: %v", f.Name, err)
		}
		b, err := io.ReadAll(rc)
		rc.Close()
		if err != nil {
			t.Fatalf("read zip part %s: %v", f.Name, err)
		}
		parts[f.Name] = b
	}
	return parts
}

func TestDocxPageIsStampedAndServed(t *testing.T) {
	srv, read, _ := newTestProxy(t, cpageServer(t, fmtTestSecret), "")

	resp, raw := fetchBytes(t, srv.URL+"/docxpage/r0915-docx-a")
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status %d, want 200", resp.StatusCode)
	}
	if resp.Header.Get("ETag") == "" {
		t.Error("DOCX page has no ETag — a crawler could not revalidate it")
	}
	if _, present := resp.Header["Cache-Control"]; present {
		t.Errorf("DOCX page sent Cache-Control %q, want it omitted (realistic header)", resp.Header.Get("Cache-Control"))
	}
	// The served bytes must themselves be a valid zip holding the document part.
	parts := docxParts(t, raw)
	if _, ok := parts["word/document.xml"]; !ok {
		t.Error("served DOCX has no word/document.xml")
	}
	recs := read()
	if len(recs) != 1 || !recs[0].Stamped() {
		t.Fatalf("the log must show the DOCX page as stamped: %+v", recs)
	}
}

// READABILITY GUARD — a minimal valid DOCX has the three parts Word requires, the
// document part is well-formed XML, and the per-page code + id are in the document
// text so an extractor (pandoc, Word, unzip) can read them out.
func TestDocxPageStructureAndMarker(t *testing.T) {
	raw := renderDocxPage("struct-id", pdfTestCode)
	parts := docxParts(t, raw)

	for _, want := range []string{"[Content_Types].xml", "_rels/.rels", "word/document.xml"} {
		if _, ok := parts[want]; !ok {
			t.Errorf("DOCX is missing required part %q", want)
		}
	}

	doc := parts["word/document.xml"]
	if doc == nil {
		t.Fatal("no word/document.xml to inspect")
	}
	// Well-formed XML, or a strict reader rejects it and the format looks broken.
	if err := wellFormedXML(doc); err != nil {
		t.Errorf("word/document.xml is not well-formed XML: %v\n%s", err, doc)
	}
	if !bytes.Contains(doc, []byte(pdfTestCode)) {
		t.Errorf("word/document.xml does not carry the per-page code:\n%s", doc)
	}
	if !bytes.Contains(doc, []byte("struct-id")) {
		t.Errorf("word/document.xml does not carry its id:\n%s", doc)
	}
}

func TestDocxPageAnswers304(t *testing.T) {
	srv, _, _ := newTestProxy(t, cpageServer(t, fmtTestSecret), "")
	first := get(t, srv.URL+"/docxpage/r0915-docx-b", nil)
	first.Body.Close()
	etag := first.Header.Get("ETag")
	if etag == "" {
		t.Fatal("no ETag on first fetch")
	}
	second := get(t, srv.URL+"/docxpage/r0915-docx-b", map[string]string{"If-None-Match": etag})
	defer second.Body.Close()
	if second.StatusCode != http.StatusNotModified {
		t.Errorf("revalidation returned %d, want 304", second.StatusCode)
	}
}

func TestDocxPageBareIs404(t *testing.T) {
	srv, _, _ := newTestProxy(t, cpageServer(t, fmtTestSecret), "")
	resp := get(t, srv.URL+"/docxpage/", nil)
	resp.Body.Close()
	if resp.StatusCode != http.StatusNotFound {
		t.Errorf("/docxpage/ with no id returned %d, want 404", resp.StatusCode)
	}
}

// Deterministic bytes → stable ETag. The zip must be written with fixed modified
// times and a fixed compression method, or the bytes drift per build and the ETag
// is unstable. This is the test the spec calls out specifically.
func TestDocxPageDeterministic(t *testing.T) {
	if !bytes.Equal(renderDocxPage("same-id", pdfTestCode), renderDocxPage("same-id", pdfTestCode)) {
		t.Error("renderDocxPage is not deterministic — zip modtimes/compression must be fixed or the ETag drifts")
	}
}
